class LocalEnvelope:
    _json: str

    @classmethod
    def from_payload(cls, payload: Mapping[str, JSONValue]) -> Self:
        memo = _DECODE_MEMO.get()
        outermost = memo is None or not _decode_memo_owned_here(memo)
        if outermost:
            # A copied Context must not inherit an active parent's successes.
            if memo is not None:
                _DECODE_MEMO.set(None)
            memo = _DecodeMemo()
            memo.token = _DECODE_MEMO.set(memo)
        try:
            raw = _object(payload, OUTER_FIELDS)
            text = _canonical(raw)
            key = (cls, text)
            cached = memo.entries.get(key)
            if cached is not None:
                result = object.__new__(cls)
                object.__setattr__(result, "_json", cached)
                return result
            tag = _text(raw["schema_version"])
            if tag not in FIELDS:
                raise ValueError("exact local semantic tag required")
            body = _object(raw["payload"], FIELDS[tag])
            original = _original(raw["original_time"])
            diagnostics = _object(raw["diagnostics"], frozenset(("utc", "monotonic")))
            for name, value in _object(diagnostics["utc"]).items():
                _text(name)
                if value is not None:
                    stamp = datetime.fromisoformat(_text(value))
                    if stamp.tzinfo is None or stamp.utcoffset() is None:
                        raise ValueError("typed diagnostic UTC required")
            if diagnostics["monotonic"] is not None:
                _number(diagnostics["monotonic"])
            original_or_request = tag.endswith((".definition.local.v1", ".original.local.v1", ".transition.local.v1", ".promotion.local.v1", ".route-input.local.v1"))
            decision: dict[str, JSONValue] | None = None
            transaction: dict[str, JSONValue] | None = None
            if original_or_request:
                if raw["decision"] is not None or raw["transaction"] is not None:
                    raise ValueError("original/request cannot self-install a current decision")
            else:
                decision = _decision(raw["decision"])
                transaction = _transaction(raw["transaction"])
                _join_decision(original, decision)
                for current_name, decision_name in (("operation_id", "operation_id"), ("operation_sha256", "operation_sha256"), ("job_id", "job_id"), ("attempt", "attempt"), ("lease_id", "lease_id"), ("epoch", "lease_epoch"), ("generation", "lease_generation"), ("row_revision", "lease_row_revision")):
                    if transaction[current_name] != decision[decision_name]:
                        raise ValueError("transaction and two-authority evidence disagree")
            _semantic(tag, body, original, diagnostics,
                      evidence_decision=decision, evidence_transaction=transaction)
            _validate_nested_local(body)
            result = object.__new__(cls)
            object.__setattr__(result, "_json", text)
            # Conservatively charge both key and result text even when shared.
            content_bytes = 2 * len(text.encode("utf-8"))
            if (key not in memo.entries and len(memo.entries) < _DECODE_MEMO_ENTRY_CAP
                    and memo.content_bytes + content_bytes <= _DECODE_MEMO_BYTE_CAP):
                memo.entries[key] = text
                memo.content_bytes += content_bytes
            return result
        finally:
            if outermost:
                _DECODE_MEMO.reset(memo.token)

    def to_payload(self) -> dict[str, JSONValue]:
        return _object(json.loads(self._json))

    def digest(self) -> str:
        return hashlib.sha256(self._json.encode()).hexdigest()

    @property
    def semantic(self) -> dict[str, JSONValue]:
        return _object(self.to_payload()["payload"])

    @property
    def local_time(self) -> LocalOriginalTime:
        return LocalOriginalTime.from_payload(_object(self.to_payload()["original_time"]))

    @property
    def decision(self) -> LocalAuthorityDecision | None:
        value = self.to_payload()["decision"]
        return None if value is None else LocalAuthorityDecision.from_payload(_object(value))

    @property
    def transaction(self) -> LocalTransactionReceipt | None:
        value = self.to_payload()["transaction"]
        return None if value is None else LocalTransactionReceipt.from_payload(_object(value))

    def detached(self) -> Self:
        return type(self).from_payload(self.to_payload())

    def string(self, name: str) -> str:
        return _text(self.semantic[name])

    def counter(self, name: str) -> int:
        return _integer(self.semantic[name])

    def object(self, name: str) -> dict[str, JSONValue]:
        return _object(self.semantic[name])

    def number(self, name: str, *, positive: bool = False) -> float:
        return _number(self.semantic[name], positive=positive)

    def boolean(self, name: str) -> bool:
        value = self.semantic[name]
        if type(value) is not bool:
            raise ValueError("strict semantic boolean required")
        return value

    def optional_string(self, name: str) -> str | None:
        value = self.semantic[name]
        return None if value is None else _text(value)

    def model[Model: BaseModel](self, name: str, model: type[Model]) -> Model:
        return _model(self.semantic[name], model)

    def optional_model[Model: BaseModel](self, name: str, model: type[Model]) -> Model | None:
        value = self.semantic[name]
        return None if value is None else _model(value, model)

    def strings(self, name: str) -> tuple[str, ...]:
        return tuple(_text(value) for value in _array(self.semantic[name]))

    def hashes(self, name: str) -> dict[str, str]:
        return {key: _sha(value) for key, value in _hashes(self.semantic[name]).items()}

    @classmethod
    def _from_local_payload(cls, payload: object, tag: str) -> Self:
        envelope = decode_local_payload(_object(payload), tag)
        result = object.__new__(cls)
        object.__setattr__(result, "_json", envelope._json)
        return result

def poll_once(self) -> bool:
        from cloud_edge_robot_arm.simulation_runtime.operational_lease import (
            OperationalLeaseError,
            _close_worker_lease_session,
            _heartbeat_lease_scope,
            _install_heartbeat_thread,
            _open_worker_lease_session,
            _worker_lease_scope,
        )

        if self._operational_lease_session is not None:
            raise OperationalLeaseError("worker poll already active")
        self._frozen_operational_time_mode = self.operational_time_mode
        session = None
        lease = None
        heartbeat = None
        stop_heartbeat = threading.Event()
        first_heartbeat = threading.Event()
        with ExitStack() as stack:
            if self._frozen_operational_time_mode in {"OPERATIONAL_LEASE_FOUNDATION_V1", "LOCAL_TEMPORAL_PUBLICATION_V1"}:
                session = _open_worker_lease_session(self)
                self._operational_lease_session = session
                stack.enter_context(_worker_lease_scope(session))
            elif self._frozen_operational_time_mode != "UTC_LEGACY_VETO":
                raise OperationalLeaseError("unsupported operational mode")
            try:
                lease = self.repository.acquire_lease(
                    worker_id=self.worker_id,
                    backend=self.backend,
                    lease_ttl_seconds=self.lease_ttl_seconds,
                )
                if lease is None:
                    return False
                owned_lease = lease
                self.active_job_id = lease.job_id
                self._heartbeat_failed.clear()

                def maintain_lease() -> None:
                    from contextlib import nullcontext
                    from datetime import UTC, datetime

                    scope = (
                        _heartbeat_lease_scope(session) if session is not None else nullcontext()
                    )
                    try:
                        with scope:
                            while not stop_heartbeat.is_set():
                                self.repository.heartbeat_lease(
                                    owned_lease.lease_id, lease_ttl_seconds=self.lease_ttl_seconds
                                )
                                self.heartbeat_at = datetime.now(UTC).isoformat()
                                first_heartbeat.set()
                                stop_heartbeat.wait(max(0.05, self.lease_ttl_seconds / 3))
                    except Exception:
                        self._heartbeat_failed.set()
                    finally:
                        first_heartbeat.set()

                heartbeat = threading.Thread(
                    target=maintain_lease, name="simulation-lease", daemon=True
                )
                if session is not None:
                    _install_heartbeat_thread(session, heartbeat)
                heartbeat.start()
                if session is not None:
                    # ACQUIRED/null-attempt is a genuine limited state before start_attempt.
                    if (
                        not first_heartbeat.wait(session.wait_cap)
                        or self._heartbeat_failed.is_set()
                    ):
                        raise OperationalLeaseError("initial ACQUIRED heartbeat failed")
                self._execute(lease.job_id, lease.lease_id)
                return True
            finally:
                if session is not None:
                    session.invalidate("worker poll finally")
                stop_heartbeat.set()
                if heartbeat is not None:
                    heartbeat.join(timeout=1)
                    if session is not None and heartbeat.is_alive():
                        session.join_failed = True
                try:
                    if session is not None and session.job_id:
                        self.repository.cleanup_operational_session(session.job_id, session=session)
                    elif session is None and lease is not None:
                        self.repository.release_lease(lease.lease_id)
                finally:
                    self.active_job_id = ""
                    self._active_task_origin = None
                    from cloud_edge_robot_arm.vision.operational_windows import _revoke_worker

                    _revoke_worker(self)
                    if session is not None:
                        _close_worker_lease_session(session, reason="worker poll closed")
                        self._operational_lease_session = None
